
INSERT INTO service_translations (service_id, language_id, title, short_description, long_description, seo_title, meta_description) VALUES
('a5a8cfeb-d375-4558-a9c2-46faf3479df5', 1, 'Amazon Marketing Agency', 'Specialized Amazon marketing agency optimizing product listings, managing PPC campaigns, and scaling your marketplace presence.', '<h2>Why Choose Advisable as Your Amazon Marketing Agency</h2><p>We help brands <strong>dominate Amazon</strong> with optimized listings, strategic PPC management, and marketplace growth tactics that maximize revenue.</p><h3>Our Amazon Marketing Services</h3><ul><li><strong>Product Listing Optimization</strong> — SEO-rich titles, bullets, and A+ content.</li><li><strong>Amazon PPC Management</strong> — Sponsored Products, Brands, and Display campaigns.</li><li><strong>Brand Store Design</strong> — Custom storefronts that convert.</li><li><strong>Review & Reputation Management</strong> — Building social proof.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/e-commerce-solutions">E-commerce Solutions →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Grow on Amazon →</a></li></ul>', 'Amazon Marketing Agency | Advisable', 'Amazon marketing agency experts. Product listing optimization, PPC management & marketplace strategy that grows your Amazon revenue.'),

('00a464fd-f754-466f-acae-dd976f40774e', 1, 'Local SEO Agency', 'Expert local SEO agency helping businesses dominate local search results, Google Maps, and location-based queries.', '<h2>Why Choose Advisable as Your Local SEO Agency</h2><p>We help businesses appear at the top of <strong>local search results</strong> and Google Maps, driving foot traffic and local leads.</p><h3>Our Local SEO Services</h3><ul><li><strong>Google Business Profile Optimization</strong> — Complete setup and ongoing management.</li><li><strong>Local Citation Building</strong> — Consistent NAP across directories.</li><li><strong>Local Content Strategy</strong> — Geo-targeted content and landing pages.</li><li><strong>Review Management</strong> — Building and managing online reputation.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/digital-agency/seo-audit">SEO Audit →</a></li><li><a href="/contact">Boost your local presence →</a></li></ul>', 'Local SEO Agency | Advisable', 'Local SEO agency boosting your visibility in local search. Google Business optimization, local citations & geo-targeted strategies.'),

('f787f1c1-183e-4752-9dd7-bb9d69afc840', 1, 'Web Development Agency', 'Professional web development agency building fast, secure, and scalable websites and web applications.', '<h2>Why Choose Advisable as Your Web Development Agency</h2><p>We build <strong>high-performance websites</strong> and web applications using modern frameworks, with a focus on speed, security, and scalability.</p><h3>Our Web Development Services</h3><ul><li><strong>Custom Website Development</strong> — Bespoke solutions tailored to your needs.</li><li><strong>Web Application Development</strong> — Complex SaaS and enterprise platforms.</li><li><strong>CMS Development</strong> — WordPress, headless CMS, and custom solutions.</li><li><strong>Performance Optimization</strong> — Core Web Vitals and speed optimization.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/web-development">Web Development →</a></li><li><a href="/digital-agency/ai-web-app-development">AI Web App Development →</a></li><li><a href="/contact">Get a free quote →</a></li></ul>', 'Web Development Agency | Advisable', 'Expert web development agency. Custom websites & web apps built with modern tech for performance, security & scalability. Get a free quote.'),

('d6f9df10-61f1-4d21-9121-a8ba6a2e27bf', 1, 'Graphic Design Agency', 'Creative graphic design agency delivering stunning visual assets and marketing materials that elevate your brand.', '<h2>Why Choose Advisable as Your Graphic Design Agency</h2><p>Our <strong>design team</strong> creates visual assets that communicate your brand story and drive engagement across every channel.</p><h3>Our Graphic Design Services</h3><ul><li><strong>Brand Identity Design</strong> — Logos, color systems, and visual guidelines.</li><li><strong>Marketing Collateral</strong> — Brochures, presentations, and print materials.</li><li><strong>Digital Design</strong> — Social media graphics, banners, and ad creatives.</li><li><strong>Packaging Design</strong> — Product packaging that stands out on shelves.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/brand-strategy">Brand Strategy →</a></li><li><a href="/digital-agency/ai-creative-studio">AI Creative Studio →</a></li><li><a href="/contact">Request a quote →</a></li></ul>', 'Graphic Design Agency | Advisable', 'Professional graphic design agency. Brand identity, marketing collateral & visual assets that make your brand stand out. Request a quote.'),

('b6f086a4-15d3-48b9-bed4-6e0b293790a1', 1, 'Growth Marketing Agency', 'Data-driven growth marketing agency using rapid experimentation and full-funnel strategies to scale your business.', '<h2>Why Choose Advisable as Your Growth Marketing Agency</h2><p>We drive <strong>sustainable growth</strong> through rapid experimentation, data analysis, and full-funnel optimization across acquisition, activation, and retention.</p><h3>Our Growth Marketing Services</h3><ul><li><strong>Growth Strategy</strong> — North Star metrics, ICPs, and channel prioritization.</li><li><strong>Experimentation Frameworks</strong> — Rapid testing across channels and funnels.</li><li><strong>Full-Funnel Optimization</strong> — From awareness to retention and referral.</li><li><strong>Analytics & Attribution</strong> — Data infrastructure for growth decisions.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/conversion-revenue-optimization">CRO →</a></li><li><a href="/contact">Let''s grow together →</a></li></ul>', 'Growth Marketing Agency | Advisable', 'Growth marketing agency driving scalable results. Rapid experimentation, full-funnel optimization & data-driven strategies. Let''s grow together.'),

('adcc34b6-3573-459a-97cd-c78ac664f6f7', 1, 'Data Analytics Agency', 'Advanced data analytics agency providing actionable insights through dashboards, attribution modeling, and predictive analytics.', '<h2>Why Choose Advisable as Your Data Analytics Agency</h2><p>We turn <strong>raw data into actionable insights</strong> with custom dashboards, attribution models, and predictive analytics that guide smarter business decisions.</p><h3>Our Data Analytics Services</h3><ul><li><strong>Custom Dashboards</strong> — Real-time reporting tailored to your KPIs.</li><li><strong>Attribution Modeling</strong> — Understanding which channels drive results.</li><li><strong>Predictive Analytics</strong> — Forecasting trends and opportunities.</li><li><strong>Data Infrastructure</strong> — Tracking setup, data warehousing, and ETL.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/tracking-attribution">Tracking & Attribution →</a></li><li><a href="/digital-agency/conversion-revenue-optimization">CRO →</a></li><li><a href="/contact">Unlock your data →</a></li></ul>', 'Data Analytics Agency | Advisable', 'Data analytics agency delivering actionable insights. Custom dashboards, attribution modeling & predictive analytics for smarter decisions.'),

('cb40ca15-de0d-43b5-9013-1553abb3cf0e', 1, 'Marketing Automation Agency', 'Expert marketing automation agency implementing HubSpot, Klaviyo, and custom workflows to nurture leads at scale.', '<h2>Why Choose Advisable as Your Marketing Automation Agency</h2><p>We implement and optimize <strong>marketing automation platforms</strong> that nurture leads, personalize experiences, and drive revenue on autopilot.</p><h3>Our Marketing Automation Services</h3><ul><li><strong>Platform Implementation</strong> — HubSpot, Klaviyo, ActiveCampaign setup.</li><li><strong>Workflow Design</strong> — Lead nurturing, onboarding, and re-engagement sequences.</li><li><strong>Personalization</strong> — Dynamic content and behavioral triggers.</li><li><strong>Integration</strong> — CRM, eCommerce, and analytics connections.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/email-marketing">Email Marketing →</a></li><li><a href="/digital-agency/ai-automations-agents">AI Automations & Agents →</a></li><li><a href="/contact">Automate your marketing →</a></li></ul>', 'Marketing Automation Agency | Advisable', 'Marketing automation agency experts. HubSpot, Klaviyo & custom workflow implementation that nurtures leads and drives revenue on autopilot.'),

('2e67a00b-f6b4-44de-a079-5e6e11ccbf41', 1, 'LinkedIn Marketing Agency', 'Specialized LinkedIn marketing agency for B2B growth through thought leadership content and targeted ad campaigns.', '<h2>Why Choose Advisable as Your LinkedIn Marketing Agency</h2><p>We help B2B brands <strong>own their LinkedIn presence</strong> with strategic content, targeted advertising, and profile optimization.</p><h3>Our LinkedIn Marketing Services</h3><ul><li><strong>Company Page Management</strong> — Content strategy and community growth.</li><li><strong>LinkedIn Ads</strong> — Sponsored content, InMail, and lead gen forms.</li><li><strong>Thought Leadership</strong> — Executive positioning and ghostwriting.</li><li><strong>Employee Advocacy</strong> — Amplifying reach through your team.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/social-media-management">Social Media Management →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Grow on LinkedIn →</a></li></ul>', 'LinkedIn Marketing Agency | Advisable', 'LinkedIn marketing agency for B2B growth. Thought leadership content, targeted ads & profile optimization that generate quality leads.'),

('1b9c02c0-63ec-4442-9142-9319767a7da1', 1, 'TikTok Marketing Agency', 'Creative TikTok marketing agency producing viral content and managing ad campaigns on the fastest-growing platform.', '<h2>Why Choose Advisable as Your TikTok Marketing Agency</h2><p>We create <strong>scroll-stopping TikTok content</strong> and manage ad campaigns that reach Gen Z and millennials at scale.</p><h3>Our TikTok Marketing Services</h3><ul><li><strong>Content Strategy & Creation</strong> — Trend-driven, platform-native content.</li><li><strong>TikTok Ads Management</strong> — In-feed, TopView, and Spark Ads campaigns.</li><li><strong>Creator Partnerships</strong> — Collaborations with TikTok influencers.</li><li><strong>TikTok Shop</strong> — Social commerce setup and optimization.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/tiktok-advertising">TikTok Advertising →</a></li><li><a href="/digital-agency/social-media-management">Social Media Management →</a></li><li><a href="/contact">Go viral on TikTok →</a></li></ul>', 'TikTok Marketing Agency | Advisable', 'TikTok marketing agency creating viral content & ad campaigns. Reach Gen Z & millennials on the fastest-growing social platform.'),

('669d1e06-4775-4841-ad3e-2dc691c1d920', 1, 'YouTube Marketing Agency', 'Strategic YouTube marketing agency optimizing channels, producing video content, and running YouTube Ads.', '<h2>Why Choose Advisable as Your YouTube Marketing Agency</h2><p>We help brands <strong>grow on YouTube</strong> with data-driven channel strategy, engaging video content, and targeted advertising.</p><h3>Our YouTube Marketing Services</h3><ul><li><strong>Channel Strategy & Optimization</strong> — Branding, SEO, and content planning.</li><li><strong>Video Production</strong> — From scripting to post-production.</li><li><strong>YouTube Ads</strong> — TrueView, bumper, and discovery campaigns.</li><li><strong>Analytics & Growth</strong> — Audience insights and performance optimization.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/ai-video-creation">AI Video Creation →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Grow your YouTube channel →</a></li></ul>', 'YouTube Marketing Agency | Advisable', 'YouTube marketing agency growing your channel. Video strategy, SEO optimization & YouTube Ads that build audience and drive conversions.'),

('21ae3aae-08c1-420a-8004-f8b26591a995', 1, 'Facebook Ads Agency', 'Expert Facebook Ads agency creating high-converting campaigns with advanced targeting on Meta platforms.', '<h2>Why Choose Advisable as Your Facebook Ads Agency</h2><p>As a <strong>Meta Business Partner</strong>, we create high-ROAS Facebook and Instagram campaigns with advanced targeting, creative testing, and full-funnel optimization.</p><h3>Our Facebook Ads Services</h3><ul><li><strong>Campaign Strategy & Setup</strong> — Funnel design and audience architecture.</li><li><strong>Creative Testing</strong> — Systematic ad creative experimentation.</li><li><strong>Audience Targeting</strong> — Lookalikes, retargeting, and interest-based segments.</li><li><strong>Reporting & Optimization</strong> — ROAS-focused performance management.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/meta-ads-campaigns">Meta Ads Campaigns →</a></li><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/contact">Get your free audit →</a></li></ul>', 'Facebook Ads Agency | Advisable', 'Facebook Ads agency delivering high-ROAS campaigns. Advanced targeting, creative testing & Meta platform expertise. Get your free audit.');
